const mensalidade = 90;
const meses = 12;
const percentual = 15;

// calcule e mostre os quatro valores aqui

exercises.solution:
const mensalidade = 90;
const meses = 12;
const percentual = 15;

const semDesconto = mensalidade * meses;
const desconto = semDesconto * percentual / 100;
const comDesconto = semDesconto - desconto;
const porMes = (semDesconto - desconto) / meses;

console.log('Sem desconto: R$', semDesconto);
console.log('Desconto: R$', desconto);
console.log('Com desconto: R$', comDesconto);
console.log('Por mês: R$', porMes);
